from core7_completion import add

add('AT_abc305_f','真实交互中的 DFS 探索与退回',
    '到新顶点时记录父亲，优先去未访问邻点；没有新邻点就沿父边退回。每条搜索树边至多去回各一次，找到 N 前最多移动 2(N−1) 次。每次输出后刷新。',
    '这道题没有一次性给出全部边，程序必须在每次移动前读取当前邻居。维护已访问标记与 DFS 父亲：有未访问邻点就前往并标记，没有则回父亲，回到父亲后重新读取它的邻居再继续。\n\n连通图中，若还没到 N 就不可能在根也无路可走，否则所有可达点都已访问而遗漏 N，矛盾。每次前往未访问点新增一条搜索树边，之后最多退回一次，所以总移动不超过 2(N−1)，满足 2N 限制。这一论证只使用已经揭示的信息，也适用于原题的自适应评测。\n\n读取字符串形式的首个反馈，遇到 OK 或 −1 立即结束，否则把它当作邻居数量。输出邻点用 endl 刷新缓冲，不能拿普通离线输入样例替代交互验证；本参考程序通过本地邻居反馈评测器核验移动合法性与次数。',
    '读取邻居总时间 O(N+M)，移动次数 O(N)，空间 O(N)。','每次反馈都要完整读完；收到 OK/−1 立即结束；输出后 flush。',r'''
int n,m;if(!(cin>>n>>m))return 0;vector<int>parent(n+1);vector<char>seen(n+1);int current=1;seen[1]=1;for(;;){string token;if(!(cin>>token))return 0;if(token=="OK"||token=="-1")return 0;int k=stoi(token),next=0;for(int i=0;i<k;i++){int v;cin>>v;if(!seen[v])next=v;}if(next){parent[next]=current;seen[next]=1;}else next=parent[current];if(!next)return 0;cout<<next<<endl;current=next;}
''',interactive='dungeon')

add('CF1919H','边分层、等权双候选与叶边锚点',
    '先询问所有边到一号边的距离，按边层数重构。用十亿权值迫使直径经过待加入边，上一层边用 n 的倍数编码。两条暂时对称的候选允许交换；一旦确定较浅叶边，就用它作为第二条重边唯一解码父边。',
    '原题是交互重构；Hacks 格式中给出的树不能直接当作原题已知输入。分层重构的起点可对照[官方提示](https://codeforces.com/blog/entry/124220)。以下实现维护已构建树及真实边编号的对应，最终只要求同构，允许交换仍对称的候选位置。\n\n把一号边两端作为初始前沿，其余边到一号边的距离用 n−2 次第二类询问取得。距离为 d 的边，其父边在上一层前沿。普通边权一，前沿边权设为 n、2n……；路径上普通边不足 n 条，所以直径除以 n 的整数部分可分离编码权值与普通长度。待加入边权十亿，远大于全部其它边权和，直径必经过它。\n\n最初还没有叶锚点，保持前沿最后两个位置在已构建部分对称，让它们同用最大编码。直径从新边出发，还会经过一个其它最大编码前沿边，所以可减去这个固定最大编码解码父边；只有最后两位置无法区分，暂把第一个这样的新边挂到其中一个，并把它也设为十亿作为本层参考。\n\n之后的新边与本层参考同时强制在直径上。若共父，路径不会经过父边，编码和为零；否则会经过两个父边，减去参考父边的编码后得到新父边。这样可以区分先前那两个等编码候选。初始根边只有一条，单独按是否跨过它判断两端。\n\n完成一层后，如果前沿某位置没有孩子，它对应一条确定叶边，且比后续待加入边更浅。若仅两个对称候选中一条为空，用至多一次第二类询问确认本层参考实际邻接哪条原边，从而找到真实叶边。以后把叶边与新边都设十亿，直径两端被固定，只经过一条待解码前沿父边，所有父边编码可不同。\n\n若尚无叶边，每个前沿位置都有孩子：有同父的两个孩子就把它们作为新的对称候选；若每个都只有一个孩子，原对称位置的两个孩子仍然对称。每条非根边恰用一次第一类询问，合计 n−2；第二类至多 n−1。所有查询值和刷新动作由本地真实树反馈器逐项核验。',
    '算法本地计算和输出 O(n²)，存储 O(n²) 的查询量上界；第一类 n−2 次、第二类至多 n−1 次。',
    '这是原题交互程序；边层数按到根边的距离；编码基数取 n；重权十亿；答案只要求同构。',r'''
int n;if(!(cin>>n))return 0;const long long HEAVY=1000000000;auto askDistance=[&](int a,int b){cout<<"? 2 "<<a+1<<' '<<b+1<<endl;int result;if(!(cin>>result)||result<0)exit(0);return result;};auto askDiameter=[&](const vector<long long>&weight){cout<<"? 1";for(long long x:weight)cout<<' '<<x;cout<<endl;long long result;if(!(cin>>result)||result<0)exit(0);return result;};vector<int>level(n-1,-1);for(int edge=1;edge<n-1;edge++)level[edge]=askDistance(0,edge);vector<int>label(n),frontier={0,1};label[0]=label[1]=0;vector<vector<int>>children(n);vector<pair<int,int>>answer={{0,1}};int created=2,anchor=-1;for(int depth=0;created<n;depth++){int width=frontier.size(),pivot=-1;vector<int>nextFrontier;for(int edge=1;edge<n-1;edge++)if(level[edge]==depth){vector<long long>weight(n-1,1);for(int i=0;i<width;i++)weight[label[frontier[i]]]=1LL*n*(anchor<0?min(i+1,width-1):i+1);if(anchor>=0)weight[anchor]=HEAVY;if(pivot>=0)weight[pivot]=HEAVY;weight[edge]=HEAVY;long long value=askDiameter(weight)-HEAVY;if(anchor>=0||pivot>=0)value-=HEAVY;int code=value/n,parentIndex=-1;if(anchor>=0)parentIndex=code-1;else if(depth==0){if(pivot<0){parentIndex=0;pivot=edge;}else parentIndex=code==0?0:1;}else{code-=width-1;if(pivot>=0&&code==-(width-1))parentIndex=width-2;else if(code==width-1){if(pivot<0){parentIndex=width-2;pivot=edge;}else parentIndex=width-1;}else parentIndex=code-1;}if(parentIndex<0||parentIndex>=width)return 0;int parent=frontier[parentIndex],v=created++;label[v]=edge;children[parent].push_back(v);nextFrontier.push_back(v);answer.push_back({parent,v});}if(created==n)break;if(nextFrontier.empty())return 0;if(anchor<0){int A=frontier[width-2],B=frontier[width-1];for(int i=0;i<width-2;i++)if(children[frontier[i]].empty()){anchor=label[frontier[i]];break;}if(anchor<0&&(children[A].empty()||children[B].empty())){if(label[A]==label[B]||(children[A].empty()&&children[B].empty()))anchor=label[A];else{int actualParent=askDistance(pivot,label[A])==0?A:B;anchor=label[actualParent==A?B:A];}}if(anchor<0){int a=-1,b=-1;for(int parent:frontier)if(children[parent].size()>=2){a=children[parent][0];b=children[parent][1];break;}if(a<0){a=children[A][0];b=children[B][0];}vector<int>ordered;for(int v:nextFrontier)if(v!=a&&v!=b)ordered.push_back(v);ordered.push_back(a);ordered.push_back(b);nextFrontier.swap(ordered);}}frontier.swap(nextFrontier);}cout<<"!"<<endl;for(auto[a,b]:answer)cout<<a+1<<' '<<b+1<<'\n';cout.flush();
''',interactive='diameter')
